WITH ca_prod AS (
  SELECT p.categorie, p.nom, SUM(v.quantite * p.prix) AS ca
  FROM ventes AS v JOIN produits AS p ON p.id = v.produit_id
  GROUP BY p.id
),
classes AS (
  SELECT categorie, nom, ca, ROW_NUMBER() OVER (PARTITION BY categorie ORDER BY ca DESC, nom) AS rang FROM ca_prod
)
SELECT categorie, nom, ca FROM classes WHERE rang = 1 ORDER BY categorie;

